    (0x9C, 0xC4, 0x6A), (0x6F, 0xA8, 0x4A), (0xC9, 0xB5, 0x6A), (0x5F, 0x7A, 0x4A), (0x3D, 0x4F, 0x32),
    (0xE6, 0xD2, 0x8A), (0xA0, 0x70, 0x4A), (0x8A, 0x8A, 0x80), (0x4A, 0x3A, 0x33), (0xF0, 0xF4, 0xF8),
