# A building's footprint in cells (width, height): its `size`, else the type's default, the original
# maps' most common size (`DEFAULT_FOOTPRINTS` in src/pack/compile.rs). A footprint is `size` cells up
# and left of the bottom-right cell, plus one more row above when wider than tall (`footprint_cells`).
FOOTPRINTS = {
    "palace": (1, 1), "town": (9, 9), "village": (4, 4), "castle": (4, 4), "fort": (2, 2), "tavern": (2, 2),
    "market": (2, 2), "church": (2, 2), "smithy": (1, 1), "shipyard": (3, 4), "altar": (3, 3),
    "dungeon_entrance": (2, 2), "ruins": (2, 2), "stone_bridge": (1, 1), "wooden_bridge": (1, 1), "obelisk": (1, 1),
}

SALT_CHOICE, SALT_CLASS, SALT_SPRITE, SALT_BUSH, SALT_MASSIF = 11, 37, 41, 53, 67


def smooth(t):
    t = min(1.0, max(0.0, t))
    return t * t * (3 - 2 * t)


def hash01(x, y, salt):
    """A deterministic value in [0, 1) for a lattice point (no Python `hash`: it is randomised)."""
    h = (x * 73856093) ^ (y * 19349663) ^ (salt * 83492791)
    h &= 0xFFFFFFFF
    h = ((h ^ (h >> 13)) * 0x5BD1E995) & 0xFFFFFFFF
    h ^= h >> 15
    h = (h * 0x27D4EB2D) & 0xFFFFFFFF
    h ^= h >> 15
    return h / 4294967296.0


def value_noise(x, y, size, salt):
    gx, gy = x / size, y / size
    ix, iy = math.floor(gx), math.floor(gy)
    fx, fy = smooth(gx - ix), smooth(gy - iy)
    a = hash01(ix, iy, salt)
    b = hash01(ix + 1, iy, salt)
    c = hash01(ix, iy + 1, salt)
    d = hash01(ix + 1, iy + 1, salt)
    top = a + (b - a) * fx
    bottom = c + (d - c) * fx
    return top + (bottom - top) * fy


def fbm(x, y, size, salt):
    """Three octaves of value noise, about [0, 1]."""
    return 0.6 * value_noise(x, y, size, salt) + 0.3 * value_noise(x, y, size / 2, salt + 1) + 0.1 * value_noise(x, y, size / 4, salt + 2)


def read_png(path):
    """(width, height, cells) of an indexed or RGB PNG; cells are terrain codes (`PALETTE` order)."""
    data = Path(path).read_bytes()
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise SystemExit(f"{path}: not a PNG")
    pos, idat, plte, width, height, depth, ctype = 8, b"", None, 0, 0, 8, 3
    while pos < len(data):
        (n,) = struct.unpack(">I", data[pos:pos + 4])
        kind = data[pos + 4:pos + 8]
        body = data[pos + 8:pos + 8 + n]
        pos += 12 + n
        if kind == b"IHDR":
            width, height, depth, ctype = struct.unpack(">IIBB", body[:10])
        elif kind == b"PLTE":
            plte = [tuple(body[i:i + 3]) for i in range(0, len(body), 3)]
        elif kind == b"IDAT":
            idat += body
    if depth != 8 or ctype not in (2, 3):
        raise SystemExit(f"{path}: only 8-bit indexed or RGB PNGs")
    bpp = 1 if ctype == 3 else 3
    raw = zlib.decompress(idat)
    stride = width * bpp
    rows = []
    prev = bytearray(stride)
    i = 0
    for _ in range(height):
        f = raw[i]
        line = bytearray(raw[i + 1:i + 1 + stride])
        i += 1 + stride
        for x in range(stride):
            a = line[x - bpp] if x >= bpp else 0
            b = prev[x]
            c = prev[x - bpp] if x >= bpp else 0
            if f == 1:
                line[x] = (line[x] + a) & 255
            elif f == 2:
                line[x] = (line[x] + b) & 255
            elif f == 3:
                line[x] = (line[x] + ((a + b) >> 1)) & 255
            elif f == 4:
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                pred = a if pa <= pb and pa <= pc else (b if pb <= pc else c)
                line[x] = (line[x] + pred) & 255
        rows.append(line)
        prev = line
    cells = []
    for line in rows:
        for x in range(width):
            if ctype == 3:
                cells.append(line[x])
            else:
                rgb = tuple(line[3 * x:3 * x + 3])
                if rgb not in PALETTE:
                    raise SystemExit(f"{path}: colour {rgb} is not a terrain colour")
                cells.append(PALETTE.index(rgb))
    return width, height, cells


def write_png(path, width, height, pixels):
    """An RGB PNG of `pixels` (a flat list of (r, g, b))."""
    raw = bytearray()
    for y in range(height):
        raw.append(0)
        for x in range(width):
            raw.extend(pixels[y * width + x])

    def chunk(kind, body):
        return struct.pack(">I", len(body)) + kind + body + struct.pack(">I", zlib.crc32(kind + body) & 0xFFFFFFFF)

    out = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0))
    out += chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b"")
    Path(path).write_bytes(out)


def strip_block(text):
    """The map text without its generated block (and the blank line before it), and the line index
    where the block began (None if there is none)."""
    lines = text.split("\n")
    start = next((i for i, l in enumerate(lines) if l.startswith("# --- generated by tools/pepelnaya-marka-dress.py")), None)
    if start is None:
        return text, None
    end = next(i for i in range(start, len(lines)) if lines[i].startswith("# --- end generated ---"))
    first = start - 1 if start > 0 and lines[start - 1] == "" else start
    last = end + 1 if end + 1 < len(lines) and lines[end + 1] == "" else end
    kept = lines[:first] + lines[last + 1:]
    return "\n".join(kept), first


def insertion_index(lines):
    """Where the block goes: before the first building, army, point or victory table that follows the
    hero's table, moved up over the comments that describe it."""
    hero = next((i for i, l in enumerate(lines) if l.strip() == "[hero]"), 0)
    head = next((i for i in range(hero + 1, len(lines)) if lines[i].startswith(("[[building]]", "[[army]]", "[[point]]", "[victory]"))), len(lines))
    i = head
    while i > hero + 1 and (lines[i - 1].strip() == "" or lines[i - 1].lstrip().startswith("#")):
        i -= 1
    return i


# The cells a trigger names, read with patterns: the triggers use TOML 1.1 (multi-line inline tables),
# which `tomllib` (TOML 1.0) does not read. A pattern miss can only leave a cell unprotected, and the
# campaign's reachability test then catches a path cut by an object; the patterns name every form the
# triggers use (`at`, `hero_at`, `go_to`, `teleport_hero`, `army_at`, `patrol`).
QUAD_RE = re.compile(r"\b(?:at|hero_at)\s*=\s*\[\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\]")
PAIR_RE = re.compile(r"\b(?:at|go_to|teleport_hero|hero_at|army_at)\s*=\s*\[\s*(\d+)\s*,\s*(\d+)\s*\]")
PATROL_RE = re.compile(r"\bpatrol\s*=\s*\[((?:\s*\[\s*\d+\s*,\s*\d+\s*\]\s*,?)+)\s*\]")
PATROL_PAIR_RE = re.compile(r"\[\s*(\d+)\s*,\s*(\d+)\s*\]")


def named_cells(pack, map_id):
    """The cells the story names on this map: ("cell", (x, y)) or ("area", (x, y, w, h)). A trigger
    with `map` applies to that map only; the dialogs name no cells."""
    out = []
    for f in sorted((pack / "triggers").glob("*.toml")):
        blocks = re.split(r"^\[\[trigger\]\]\s*$", f.read_text(encoding="utf-8"), flags=re.M)[1:]
        for block in blocks:
            on = re.search(r'^map\s*=\s*"([^"]+)"', block, re.M)
            if on and on.group(1) != map_id:
                continue
            for m in QUAD_RE.finditer(block):
                out.append(("area", tuple(int(v) for v in m.groups())))
            for m in PAIR_RE.finditer(block):
                out.append(("cell", (int(m.group(1)), int(m.group(2)))))
            for m in PATROL_RE.finditer(block):
                for q in PATROL_PAIR_RE.finditer(m.group(1)):
                    out.append(("cell", (int(q.group(1)), int(q.group(2)))))
    return out


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("map_dir", type=Path, help="the map's folder (maps/<id>)")
    ap.add_argument("--seed", type=int, required=True)
    ap.add_argument("--preview", type=Path, help="write an RGB PNG of the terrain with the objects (for a look, not for git)")
    args = ap.parse_args()

    map_id = args.map_dir.name
    if map_id not in MAPS:
        sys.exit(f"{map_id}: no dressing configured (MAPS in this tool)")
    pack = args.map_dir.parent.parent
    w, h, cells = read_png(args.map_dir / "terrain.png")
    kinds = [TERRAIN[c] for c in cells]
    text = (args.map_dir / "map.toml").read_text(encoding="utf-8")
    hand_text, _ = strip_block(text)
    spec = tomllib.loads(hand_text)
    cfg = MAPS[map_id]
    rng_salt = args.seed * 1000003 + sum(ord(ch) * (i + 1) for i, ch in enumerate(map_id)) * 7919

    def inside(x, y):
        return 0 <= x < w and 0 <= y < h

    def idx(x, y):
        return y * w + x

    # Protection: a cell may hold an object only if `free[i]` is set.
    free = [kinds[i] in LAND_COVER for i in range(w * h)]
    near_road = [False] * (w * h)
    near_ford = [False] * (w * h)
    keep = [False] * (w * h)  # the story's cells and their rings: no object at all
    for i, k in enumerate(kinds):
        if k == "road":
            free[i] = False
        if k == "shallows_fords":
            free[i] = False
    for y in range(h):
        for x in range(w):
            if kinds[idx(x, y)] == "road":
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if inside(x + dx, y + dy):
                            near_road[idx(x + dx, y + dy)] = True
            if kinds[idx(x, y)] == "shallows_fords":
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if inside(x + dx, y + dy):
                            near_ford[idx(x + dx, y + dy)] = True

    def ring(x, y, r):
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if inside(x + dx, y + dy):
                    keep[idx(x + dx, y + dy)] = True

    def area(x0, y0, aw, ah):
        for yy in range(y0, y0 + ah):
            for xx in range(x0, x0 + aw):
                if inside(xx, yy):
                    keep[idx(xx, yy)] = True

    # The hero, the buildings, the armies and the points: the cell and its ring. A building's ring
    # goes round its whole footprint.
    ring(*spec["hero"]["cell"], 1)
    for b in spec.get("building", []):
        sx, sy = b.get("size", FOOTPRINTS[b["type"]])
        ax, ay = b["cell"]
        for j in range(sy + (1 if sx > sy else 0)):
            for i in range(sx):
                ring(ax - i, ay - j, 1)
    for table in ("army", "point"):
        for item in spec.get(table, []):
            ring(*item["cell"], 1)
    for kind, named in named_cells(pack, map_id):
        if kind == "area":
            area(named[0], named[1], named[2], named[3])
        else:
            ring(named[0], named[1], 1)

    occupied = [False] * (w * h)
    for o in spec.get("object", []):
        x, y = o["cell"]
        if inside(x, y):
            occupied[idx(x, y)] = True

    def allowed(x, y):
        return inside(x, y) and free[idx(x, y)] and not keep[idx(x, y)] and not occupied[idx(x, y)]

    chosen = {}  # cell index -> (kind, sprite, anchor x, anchor y)

    def place(x, y, kind, sprite=None):
        i = idx(x, y)
        occupied[i] = True
        if sprite is None:
            pool = POOLS[kind]
            sprite = pool[int(rng(x, y, SALT_SPRITE) * len(pool))]
        chosen[i] = (kind, sprite, x, y)

    # Massifs (hills, mountains, stones over a square of sprite // 10 cells a side).
    def massif_fits(x, y, side):
        for j in range(side):
            for i in range(side):
                if not allowed(x - i, y - j) or near_road[idx(x - i, y - j)] or near_ford[idx(x - i, y - j)]:
                    return False
        return True

    rng = lambda x, y, salt: hash01(x, y, rng_salt + salt)  # noqa: E731
    # Hill zones: around each hand-placed hill or mountain of the map (the author's barrows and ridges).
    zones = list(cfg.get("hills", []))
    hand = cfg.get("hand_hills")
    if hand:
        for o in spec.get("object", []):
            if o["kind"] in ("hills", "mountains"):
                x, y = o["cell"]
                r = hand["radius"]
                zones.append({"rect": (max(0, x - r), max(0, y - r), min(w - 1, x + r), min(h - 1, y + r)), "count": hand["count"], "sides": (2, 3)})
    for zone in zones:
        x0, y0, x1, y1 = zone["rect"]
        placed = 0
        tries = 0
        while placed < zone["count"] and tries < 400:
            tries += 1
            x = x0 + int(rng(tries, 1, SALT_MASSIF) * (x1 - x0 + 1))
            y = y0 + int(rng(tries, 2, SALT_MASSIF) * (y1 - y0 + 1))
            side = zone["sides"][int(rng(tries, 3, SALT_MASSIF) * len(zone["sides"]))]
            if massif_fits(x, y, side):
                for j in range(side):
                    for i in range(side):
                        occupied[idx(x - i, y - j)] = True
                chosen[idx(x, y)] = ("hill", 10 * side + int(rng(x, y, SALT_SPRITE) * 4), x, y)
                placed += 1
    # Hill zones: a few stones among the hills (blocking: only where they keep a clear cell around).
    for zone in zones:
        x0, y0, x1, y1 = zone["rect"]
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if allowed(x, y) and not near_road[idx(x, y)] and rng(x, y, SALT_CLASS + 5) < 0.04:
                    place(x, y, "stones", None)

    # Terrain objects: copses and clearings, the density of the original scaled by the mood.
    report = {}
    for terrain in MIX:
        mood = cfg["mood"].get(terrain, 1.0)
        cand = [i for i in range(w * h) if kinds[i] == terrain and allowed(i % w, i // w)]
        report[terrain] = [len(cand), ORIGINAL_DENSITY[terrain] * mood, 0]
        if not cand:
            continue
        masks = {}
        for i in cand:
            x, y = i % w, i // w
            v = fbm(x, y, 9.0, 101)
            masks[i] = smooth((v - 0.42) / 0.3)
        # Burned ground is scattered rather than in copses: its clustering is blended toward the mean.
        spread = SCATTER.get(terrain, 0.0)
        if spread:
            mean = sum(masks.values()) / len(masks)
            for i in cand:
                masks[i] = (1 - spread) * masks[i] + spread * mean
        target = ORIGINAL_DENSITY[terrain] / 100.0 * mood * len(cand)
        total = sum(masks.values()) or 1.0
        k = target / total
        mix = MIX[terrain]
        weights = sum(mix.values())
        for i in cand:
            if occupied[i] or chosen.get(i):
                continue
            x, y = i % w, i // w
            p = min(0.95, k * masks[i])
            if rng(x, y, SALT_CHOICE) >= p:
                continue
            pick = rng(x, y, SALT_CLASS) * weights
            kind = None
            for name, part in mix.items():
                if pick < part:
                    kind = name
                    break
                pick -= part
            kind = kind or next(iter(mix))
            # Blocking objects keep the roads and fords clear around them; thickets only in a copse's core.
            if kind in ("thicket", "stones", "mountain") and near_road[idx(x, y)]:
                kind = "tree" if "tree" in mix else "dead"
            if kind == "thicket" and masks[i] < 0.6:
                kind = "tree" if "tree" in mix else "bush"
            if kind == "mountain" and near_road[idx(x, y)]:
                kind = "dead"
            place(x, y, kind)
            report[terrain][2] += 1

    # Bushes along the borders between land kinds.
    border = cfg.get("border_bush", 0.0)
    for i in range(w * h):
        if occupied[i] or not allowed(i % w, i // w):
            continue
        x, y = i % w, i // w
        mine = kinds[i]
        if not any(inside(x + dx, y + dy) and kinds[idx(x + dx, y + dy)] in LAND_COVER and kinds[idx(x + dx, y + dy)] != mine
                   for dy in (-1, 0, 1) for dx in (-1, 0, 1)):
            continue
        if rng(x, y, SALT_BUSH) < border:
            place(x, y, "bush")

    # The block: one entry per object, the kinds written as the map format names them.
    entries = []
    counts = {}
    for i in sorted(chosen, key=lambda i: (i // w, i % w)):
        kind, sprite, x, y = chosen[i]
        name = KIND_OF[kind]
        counts[name] = counts.get(name, 0) + 1
        entries.append(f'[[object]]\nkind = "{name}"\ncell = [{x}, {y}]\nsprite = {sprite}\n')
    block = [f"# --- generated by tools/pepelnaya-marka-dress.py, seed {args.seed} ---",
             "# Objects of the terrain (not hand-placed): forests and copses with clearings, bushes on the",
             "# borders, reeds on the marsh, dead trees on the burned land, rocks, hills. A rerun replaces this block.",
             ""]
    block_text = "\n".join(block) + "\n" + "\n".join(entries) + "# --- end generated ---"

    stripped, _ = strip_block(text)
    lines = stripped.split("\n")
    at = insertion_index(lines)
    new_lines = lines[:at] + [""] + block_text.split("\n") + [""] + lines[at:]
    new_text = "\n".join(new_lines)
    if new_text != text:
        (args.map_dir / "map.toml").write_text(new_text, encoding="utf-8")

    hand = len(spec.get("object", []))
    print(f"{map_id}: {w}x{h} cells, hand-placed objects {hand}, generated {len(chosen)}, total {hand + len(chosen)}")
    for name in sorted(counts):
        print(f"  {name:12s} {counts[name]}")
    per100 = 100.0 * (hand + len(chosen)) / (w * h)
    print(f"  per 100 cells {per100:.1f}")
    for terrain, (cand, density, placed) in report.items():
        if cand:
            print(f"  {terrain:14s} open {cand:5d}  target {density:5.1f}/100  placed {placed:5d}  ({100.0 * placed / cand:.1f}% of open)")

    if args.preview:
        scale = max(2, 800 // w)
        pixels = []
        objs = {(i % w, i // w): chosen[i][0] for i in chosen}
        hand_objs = {tuple(o["cell"]): o["kind"] for o in spec.get("object", [])}
        # A massif is drawn over its whole square, in the same tint (classes 1–8 cover sprite // 10 cells).
        covered = set()
        for i, (kind, sprite, x, y) in chosen.items():
            if KIND_OF[kind] in MASSIF_NAMES:
                side = sprite // 10
                covered.update((x - a, y - b) for a in range(side) for b in range(side))
        for py in range(h * scale):
            for px in range(w * scale):
                x, y = px // scale, py // scale
                colour = PALETTE[cells[idx(x, y)]]
                cx, cy = px % scale, py % scale
                kind = None
                if (x, y) in objs:
                    kind = KIND_OF[objs[(x, y)]]
                elif (x, y) in hand_objs:
                    kind = hand_objs[(x, y)]
                if kind and scale // 4 <= cx < scale - scale // 4 and scale // 4 <= cy < scale - scale // 4:
                    colour = PREVIEW.get(kind, (0, 0, 0))
                if (x, y) in covered and kind in MASSIF_NAMES:
                    colour = PREVIEW[kind]
                pixels.append(colour)
        write_png(args.preview, w * scale, h * scale, pixels)
        print(f"  preview {args.preview}")


if __name__ == "__main__":
    main()
